// ============================================================
// Code node n8n — mode "Run Once for All Items"
// But : générer UN SEUL email (objet + corps HTML) regroupant
// tous les dossiers présentant un écart entre le montant facturé
// et le montant net réceptionné (BR), à destination du Service Juridique,
// après dépassement du délai de traitement de 7 jours.
// ============================================================

const items = $input.all().map(i => i.json);

// --- Email statique du destinataire (Service Juridique) ---
const EMAIL_JURIDIQUE = 'b.jawad@jbel-annour.com'; // <-- à remplacer par l'adresse réelle

// --- Helpers ---
function fm(n) {
  const x = parseFloat(n);
  if (isNaN(x)) return n ?? '-';
  return x.toLocaleString('fr-FR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' MAD';
}

function modeLabel(m) {
  const map = { 3: 'Réception total', 2: 'Réception multiple' };
  return map[m] || `Mode ${m}`;
}

// Parse une date au format JJ/MM/AAAA -> objet Date
function parseDateFr(dateStr) {
  if (!dateStr) return null;
  const parts = dateStr.split('/');
  if (parts.length !== 3) return null;
  const [jour, mois, annee] = parts.map(p => parseInt(p, 10));
  if (!jour || !mois || !annee) return null;
  return new Date(annee, mois - 1, jour);
}

// Calcule le nombre de jours écoulés depuis DateFacture
function joursEcoules(dateStr) {
  const d = parseDateFr(dateStr);
  if (!d) return null;
  const now = new Date();
  const diffMs = now.setHours(0,0,0,0) - d.setHours(0,0,0,0);
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

const SEUIL_JOURS = 7;

// --- Regroupement par fournisseur (CODE_FRNS) ---
const groups = {};
for (const it of items) {
  const key = it.CODE_FRNS || 'INCONNU';
  if (!groups[key]) {
    groups[key] = { raison: (it.Raison || '').trim(), comptable: it.Comptable || '-', lignes: [] };
  }
  const jours = joursEcoules(it.DateFacture);
  groups[key].lignes.push({ ...it, jours_ecoules: jours, depasse_seuil: jours !== null && jours >= SEUIL_JOURS });
}

const totalLignes = items.length;
const totalFournisseurs = Object.keys(groups).length;
const totalEcart = items.reduce((s, it) => s + (parseFloat(it.Ecart_Global) || 0), 0);
const totalDepasses = items.filter(it => {
  const j = joursEcoules(it.DateFacture);
  return j !== null && j >= SEUIL_JOURS;
}).length;

// --- Construction du tableau HTML ---
let rowsHtml = '';
for (const [code, g] of Object.entries(groups)) {
  rowsHtml += `
    <tr>
      <td colspan="10" style="padding:8px;background:#eef1f5;font-weight:bold;">
        ${g.raison} (${code}) — Comptable en charge : ${g.comptable}
      </td>
    </tr>`;
  for (const l of g.lignes) {
    const ecart = parseFloat(l.Ecart_Global) || 0;
    const ecartColor = ecart > 0 ? '#b00020' : '#222';

    const badgeRetard = l.depasse_seuil
      ? `<span style="background:#b00020;color:#fff;padding:2px 6px;border-radius:4px;font-size:11px;font-weight:bold;">
           +${l.jours_ecoules}j
         </span>`
      : `<span style="color:#888;font-size:11px;">${l.jours_ecoules !== null ? l.jours_ecoules + 'j' : '-'}</span>`;

    rowsHtml += `
    <tr>
      <td style="padding:6px;border:1px solid #ddd;font-weight:bold;color:#2d5a87;">${l.N_Depot || '-'}</td>
      <td style="padding:6px;border:1px solid #ddd;">${l.BC || '-'}</td>
      <td style="padding:6px;border:1px solid #ddd;">${l.Bon_Reception || '-'}</td>
      <td style="padding:6px;border:1px solid #ddd;">${l.FactureFrns || '-'}</td>
      <td style="padding:6px;border:1px solid #ddd;">${l.DateFacture || '-'}</td>
      <td style="padding:6px;border:1px solid #ddd;text-align:center;">${badgeRetard}</td>
      <td style="padding:6px;border:1px solid #ddd;text-align:right;">${fm(l.Mnt_Facture)}</td>
      <td style="padding:6px;border:1px solid #ddd;text-align:right;">${fm(l.Montant_Net_Par_BR)}</td>
      <td style="padding:6px;border:1px solid #ddd;text-align:right;color:${ecartColor};font-weight:bold;">${fm(l.Ecart_Global)}</td>
      <td style="padding:6px;border:1px solid #ddd;">${modeLabel(l.mode_reception)}</td>
    </tr>`;
  }
}

// --- Objet ---
const objet = `⚠️ Alerte Juridique – Délai de 7j dépassé – ${totalDepasses} dossier(s) non traité(s) sur ${totalLignes}`;

// --- Corps HTML ---
const corps = `
<div style="font-family:Arial, sans-serif; font-size:14px; color:#222;">
  <p>Bonjour,</p>

  <p>
    Nous portons à votre attention <strong>${totalLignes} dossier(s)</strong>, répartis sur
    <strong>${totalFournisseurs} fournisseur(s)</strong>, présentant un écart entre le
    <strong>montant facturé</strong> et le <strong>montant net réceptionné (BR)</strong>.
  </p>

  <p style="background:#fdecea;border-left:4px solid #b00020;padding:10px 14px;margin:16px 0;">
    <strong>${totalDepasses} dossier(s)</strong> sur ${totalLignes} dépassent désormais le délai
    de traitement de <strong>${SEUIL_JOURS} jours</strong> depuis la date de facture, sans régularisation
    à ce jour. Une escalade vers le <strong>Service Juridique</strong> est requise pour ces dossiers.
  </p>

  <p>
    Merci de bien vouloir analyser ces écarts avec les fournisseurs et comptables concernés,
    et de statuer sur les régularisations nécessaires en priorité pour les dossiers signalés en retard.
  </p>

  <table style="border-collapse:collapse;width:100%;margin-top:15px;">
    <thead>
      <tr style="background:#333;color:#fff;">
        <th style="padding:6px;border:1px solid #ddd;text-align:left;">N° DFF</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:left;">BC</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:left;">BR</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:left;">N° Facture</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:left;">Date Facture</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:center;">Délai</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:right;">Mnt Facture</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:right;">Mnt Net BR</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:right;">Écart</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:left;">Mode réception</th>
      </tr>
    </thead>
    <tbody>
      ${rowsHtml}
    </tbody>
  </table>

  <p>Cordialement,<br/>Le service SI/AI</p>
</div>
`;

return [
  {
    json: {
      objet,
      corps,
      email_destinataire: EMAIL_JURIDIQUE,
      total_lignes: totalLignes,
      total_fournisseurs: totalFournisseurs,
      total_ecart: totalEcart,
      total_depasses: totalDepasses,
      seuil_jours: SEUIL_JOURS
    }
  }
];

// ============================================================
// Code node n8n — mode "Run Once for All Items"
// But : générer UN SEUL email d'ESCALADE au DGA (objet + corps HTML)
// regroupant tous les dossiers présentant un écart entre le montant
// facturé et le montant net réceptionné (BR), ayant dépassé le délai
// de 14 jours sans régularisation malgré l'alerte Juridique.
// ============================================================

const items = $input.all().map(i => i.json);

// --- Email statique du destinataire (DGA) ---
const EMAIL_DGA = 'b.fani@jbel-annour.com'; // <-- à remplacer par l'adresse réelle

// --- Helpers ---
function fm(n) {
  const x = parseFloat(n);
  if (isNaN(x)) return n ?? '-';
  return x.toLocaleString('fr-FR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' MAD';
}

function modeLabel(m) {
  const map = { 3: 'Réception total', 2: 'Réception multiple' };
  return map[m] || `Mode ${m}`;
}

// Parse une date au format JJ/MM/AAAA -> objet Date
function parseDateFr(dateStr) {
  if (!dateStr) return null;
  const parts = dateStr.split('/');
  if (parts.length !== 3) return null;
  const [jour, mois, annee] = parts.map(p => parseInt(p, 10));
  if (!jour || !mois || !annee) return null;
  return new Date(annee, mois - 1, jour);
}

// Calcule le nombre de jours écoulés depuis DateFacture
function joursEcoules(dateStr) {
  const d = parseDateFr(dateStr);
  if (!d) return null;
  const now = new Date();
  const diffMs = now.setHours(0,0,0,0) - d.setHours(0,0,0,0);
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

const SEUIL_JOURS = 14;

// --- Regroupement par fournisseur (CODE_FRNS) ---
const groups = {};
for (const it of items) {
  const key = it.CODE_FRNS || 'INCONNU';
  if (!groups[key]) {
    groups[key] = { raison: (it.Raison || '').trim(), comptable: it.Comptable || '-', lignes: [] };
  }
  const jours = joursEcoules(it.DateFacture);
  groups[key].lignes.push({ ...it, jours_ecoules: jours, depasse_seuil: jours !== null && jours >= SEUIL_JOURS });
}

const totalLignes = items.length;
const totalFournisseurs = Object.keys(groups).length;
const totalEcart = items.reduce((s, it) => s + (parseFloat(it.Ecart_Global) || 0), 0);
const joursMax = Math.max(...items.map(it => joursEcoules(it.DateFacture) ?? 0));

// --- Construction du tableau HTML ---
let rowsHtml = '';
for (const [code, g] of Object.entries(groups)) {
  rowsHtml += `
    <tr>
      <td colspan="10" style="padding:8px;background:#eef1f5;font-weight:bold;">
        ${g.raison} (${code}) — Comptable en charge : ${g.comptable}
      </td>
    </tr>`;
  for (const l of g.lignes) {
    const ecart = parseFloat(l.Ecart_Global) || 0;
    const ecartColor = ecart > 0 ? '#b00020' : '#222';

    rowsHtml += `
    <tr>
      <td style="padding:6px;border:1px solid #ddd;font-weight:bold;color:#2d5a87;">${l.N_Depot || '-'}</td>
      <td style="padding:6px;border:1px solid #ddd;">${l.BC || '-'}</td>
      <td style="padding:6px;border:1px solid #ddd;">${l.Bon_Reception || '-'}</td>
      <td style="padding:6px;border:1px solid #ddd;">${l.FactureFrns || '-'}</td>
      <td style="padding:6px;border:1px solid #ddd;">${l.DateFacture || '-'}</td>
      <td style="padding:6px;border:1px solid #ddd;text-align:center;color:#b00020;font-weight:bold;">${l.jours_ecoules !== null ? l.jours_ecoules + ' j' : '-'}</td>
      <td style="padding:6px;border:1px solid #ddd;text-align:right;">${fm(l.Mnt_Facture)}</td>
      <td style="padding:6px;border:1px solid #ddd;text-align:right;">${fm(l.Montant_Net_Par_BR)}</td>
      <td style="padding:6px;border:1px solid #ddd;text-align:right;color:${ecartColor};font-weight:bold;">${fm(l.Ecart_Global)}</td>
      <td style="padding:6px;border:1px solid #ddd;">${modeLabel(l.mode_reception)}</td>
    </tr>`;
  }
}

// --- Objet ---
const objet = `[ESCALADE DGA] ${totalLignes} dossier(s) en écart facture/BR – dépassement du délai de 14 jours sans régularisation`;

// --- Corps HTML ---
const corps = `
<div style="font-family:Arial, sans-serif; font-size:14px; color:#222;">
  <p>Monsieur le Directeur Général Adjoint,</p>

  <p>
    Nous vous informons que <strong>${totalLignes} dossier(s)</strong>, répartis sur
    <strong>${totalFournisseurs} fournisseur(s)</strong>, présentent un écart entre le
    <strong>montant facturé</strong> et le <strong>montant net réceptionné (BR)</strong>,
    et ont désormais dépassé le <strong>délai de 14 jours</strong> sans régularisation,
    malgré l'alerte préalablement transmise au Service Juridique.
  </p>

  <p style="background:#fdecea;border-left:4px solid #b00020;padding:10px 14px;margin:16px 0;">
    À ce jour, <strong>aucune intervention n'a été constatée</strong> sur ces dossiers, dont
    certains sont en attente depuis <strong>${joursMax} jour(s)</strong>. Nous portons ce
    blocage à votre connaissance afin qu'une décision puisse être prise au niveau adéquat.
  </p>

  <p>
    Merci de bien vouloir arbitrer sur les régularisations nécessaires pour ces dossiers en
    dépassement critique.
  </p>

  <table style="border-collapse:collapse;width:100%;margin-top:15px;">
    <thead>
      <tr style="background:#333;color:#fff;">
        <th style="padding:6px;border:1px solid #ddd;text-align:left;">N° DFF</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:left;">BC</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:left;">BR</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:left;">N° Facture</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:left;">Date Facture</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:center;">Jours écoulés</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:right;">Mnt Facture</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:right;">Mnt Net BR</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:right;">Écart</th>
        <th style="padding:6px;border:1px solid #ddd;text-align:left;">Mode réception</th>
      </tr>
    </thead>
    <tbody>
      ${rowsHtml}
    </tbody>
  </table>

  <p style="margin-top:15px;">
    <strong>Total : ${totalLignes} ligne(s) — Écart cumulé : ${fm(totalEcart)}</strong>
  </p>

  <p>
    Nous restons à votre disposition pour tout complément d'information et vous remercions
    de votre intervention.
  </p>

  <p>Cordialement,<br/>Le service SI/AI</p>
</div>
`;

return [
  {
    json: {
      objet,
      corps,
      email_destinataire: EMAIL_DGA,
      total_lignes: totalLignes,
      total_fournisseurs: totalFournisseurs,
      total_ecart: totalEcart,
      jours_max: joursMax,
      seuil_jours: SEUIL_JOURS
    }
  }
];

// Node Code (JS) — n8n
// Mode : "Run Once for All Items"
// Regroupe les lignes du rapprochement par numéro de facture fournisseur (FactureFrns)

const items = $input.all();

const groups = {};

for (const item of items) {
  const facture = (item.json.FactureFrns || 'SANS_NUMERO').toString().trim();

  if (!groups[facture]) {
    groups[facture] = {
      FactureFrns: facture,
      DateFacture: item.json.DateFacture || '',
      CODE_FRNS: item.json.CODE_FRNS || '',
      Raison: item.json.Raison || '',
      Comptable: item.json.Comptable || '',
      nombre_lignes: 0,
      lignes: [],
      contient_critique: false
    };
  }

  groups[facture].nombre_lignes += 1;
  groups[facture].lignes.push(item.json);

  if (item.json.est_critique) {
    groups[facture].contient_critique = true;
  }
}

// Transforme l'objet en tableau d'items n8n
return Object.values(groups).map(g => ({ json: g }));
